function escapeHtml(str) {
    if (typeof str !== 'string') {
        return ''; // Return empty string for non-string inputs
    }
    return str.replace(/&/g, '&amp;')
              .replace(/</g, '&lt;')
              .replace(/>/g, '&gt;')
              .replace(/"/g, '&quot;')
              .replace(/'/g, '&#39;');
}

